insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4195d2ca-e36c-4bd9-bb7e-e178e5d589ca', 'de', 'Du fängst Gespräche gut an, aber sie werden schnell peinlich. Wo liegt dein Knackpunkt?', '["Den Gesprächsfluss halten und sie dabeihalten", "Opener rüberbringen", "Zum Abschluss kommen und Nummern bekommen", "Körperlich weitergehen"]'::jsonb, 'Die Ergebnisse ändern sich, wenn du gezielt das schwächste Glied der Begegnung übst.')
